[IO.File]::WriteAllBytes($archive,[Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne '0fbcd11e4d27636decfe0e2c4224148564ae2b4ede3ea03f6d74208ce310bff2') { throw 'Pacote alterado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $tempRoot
$appScript = Join-Path $tempRoot 'Preparar-Importacao-Livre-1.07.ps1'
$siteScript = Join-Path $tempRoot 'Publicar-Central-Listas-1.07.ps1'
if ((Get-FileHash -LiteralPath $appScript -Algorithm SHA256).Hash.ToLowerInvariant() -ne '3c927275d4d0106659b35e7ffbc17bf5c5e3f6d52a4c6aee0a7cf55beea866c3' -or (Get-FileHash -LiteralPath $siteScript -Algorithm SHA256).Hash.ToLowerInvariant() -ne '8c74e6234cb42bbb6cb87697e71fce3e589e8b94fcff96e965635a4da6fe15c4') { throw 'Instalador alterado.' }
$executor = (Get-Process -Id $PID).Path
if (-not $SomenteSite) {
    & $executor -NoProfile -ExecutionPolicy Bypass -File $appScript -Projeto $Projeto -Verificar
    if ($LASTEXITCODE -ne 0) { throw 'Projeto divergente. Nada foi publicado na central.' }
    $appArgs = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$appScript,'-Projeto',$Projeto)
    if ($Emulador) { $appArgs += @('-Emulador',$Emulador) }
    & $executor @appArgs
    if ($LASTEXITCODE -ne 0) { throw 'Atualizacao do app nao concluida. Nada foi publicado na central.' }
}
if (-not $SomenteApp) {
    $siteArgs = @('-NoProfile','-ExecutionPolicy','Bypass','-File',$siteScript,'-PastaDestino',$PastaDestino)
    if ($NaoPublicarSite) { $siteArgs += '-NaoPublicar' }
    & $executor @siteArgs
    if ($LASTEXITCODE -ne 0) { throw 'Central nao publicada. Verifique a autenticacao do Wrangler. O app atualizado foi preservado; tente novamente com -SomenteSite.' }
}
Write-Host 'Concluido. No site: nome e link -> Validar link -> conferir formato -> Enviar lista.'
